import json
import os
from typing import Any, Dict, List, Optional

import boto3


def _normalize_bbox(box: Any) -> Optional[Dict[str, float]]:
    if not box:
        return None

    if isinstance(box, dict):
        keys = set(box.keys())
        if {"Left", "Top", "Width", "Height"} <= keys:
            return {
                "left": float(box["Left"]),
                "top": float(box["Top"]),
                "width": float(box["Width"]),
                "height": float(box["Height"]),
            }
        if {"left", "top", "width", "height"} <= keys:
            return {
                "left": float(box["left"]),
                "top": float(box["top"]),
                "width": float(box["width"]),
                "height": float(box["height"]),
            }

    if isinstance(box, (list, tuple)) and len(box) >= 4:
        return {
            "left": float(box[0]),
            "top": float(box[1]),
            "width": float(box[2]),
            "height": float(box[3]),
        }

    return None


def _extract_text_from_query_result(document_analysis: Dict[str, Any]) -> Dict[str, Any]:
    result: Dict[str, Any] = {"key_values": []}

    for block in document_analysis.get("Blocks", []):
        if block.get("BlockType") != "KEY_VALUE_SET":
            continue
        entity_types = set(block.get("EntityTypes", []))
        if "KEY" not in entity_types:
            continue

        key_text_parts: List[str] = []
        value_text_parts: List[str] = []

        relationships = block.get("Relationships", [])
        child_ids = []
        value_ids = []
        for rel in relationships:
            if rel.get("Type") == "CHILD":
                child_ids.extend(rel.get("Ids", []))
            elif rel.get("Type") == "VALUE":
                value_ids.extend(rel.get("Ids", []))

        blocks_by_id = {b.get("Id"): b for b in document_analysis.get("Blocks", [])}

        for cid in child_ids:
            child = blocks_by_id.get(cid)
            if not child:
                continue
            if child.get("BlockType") == "WORD":
                key_text_parts.append(child.get("Text", ""))
            elif child.get("BlockType") == "SELECTION_ELEMENT" and child.get("SelectionStatus") == "SELECTED":
                key_text_parts.append("X")

        for vid in value_ids:
            value_block = blocks_by_id.get(vid)
            if not value_block:
                continue
            for rel in value_block.get("Relationships", []):
                if rel.get("Type") != "CHILD":
                    continue
                for cid in rel.get("Ids", []):
                    child = blocks_by_id.get(cid)
                    if not child:
                        continue
                    if child.get("BlockType") == "WORD":
                        value_text_parts.append(child.get("Text", ""))
                    elif child.get("BlockType") == "SELECTION_ELEMENT" and child.get("SelectionStatus") == "SELECTED":
                        value_text_parts.append("X")

        key_text = " ".join(t for t in key_text_parts if t).strip()
        value_text = " ".join(t for t in value_text_parts if t).strip()

        if key_text:
            result["key_values"].append(
                {
                    "key": key_text,
                    "value": value_text,
                    "key_bbox": _normalize_bbox(block.get("Geometry", {}).get("BoundingBox")),
                    "value_bbox": None,
                }
            )

    return result


def extract_key_value_pairs(
    document_path: Optional[str] = None,
    document_bytes: Optional[bytes] = None,
    content_type: str = "application/pdf",
    feature_types: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """
    Extract key-value pairs from a form-like document using Amazon Textract.

    Args:
        document_path: Path to a local document file to analyze.
        document_bytes: Raw bytes for the document. If provided, document_path is ignored.
        content_type: MIME type when passing document_bytes.
        feature_types: Textract features. Defaults to ["FORMS"].

    Returns:
        Dictionary with extracted key_values and metadata.
    """
    if feature_types is None:
        feature_types = ["FORMS"]

    textract = boto3.client("textract")

    if document_bytes is None:
        if not document_path:
            raise ValueError("Either document_path or document_bytes must be provided.")
        with open(document_path, "rb") as f:
            document_bytes = f.read()

    response = textract.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=feature_types,
    )

    parsed = _extract_text_from_query_result(response)
    parsed["provider"] = "amazon-textract"
    parsed["content_type"] = content_type
    parsed["raw_response"] = response
    return parsed


def extract_key_value_pairs_from_s3(
    bucket: str,
    key: str,
    feature_types: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """
    Extract key-value pairs from an S3-hosted document using Amazon Textract.

    Args:
        bucket: S3 bucket name.
        key: S3 object key.
        feature_types: Textract features. Defaults to ["FORMS"].

    Returns:
        Dictionary with extracted key_values and metadata.
    """
    if feature_types is None:
        feature_types = ["FORMS"]

    textract = boto3.client("textract")
    response = textract.analyze_document(
        Document={"S3Object": {"Bucket": bucket, "Name": key}},
        FeatureTypes=feature_types,
    )

    parsed = _extract_text_from_query_result(response)
    parsed["provider"] = "amazon-textract"
    parsed["source"] = {"bucket": bucket, "key": key}
    parsed["raw_response"] = response
    return parsed


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="Extract key-value pairs from a form-like document using Amazon Textract.")
    parser.add_argument("document_path", nargs="?", help="Path to the input document")
    parser.add_argument("--s3-bucket", help="S3 bucket name")
    parser.add_argument("--s3-key", help="S3 object key")
    args = parser.parse_args()

    if args.s3_bucket and args.s3_key:
        result = extract_key_value_pairs_from_s3(args.s3_bucket, args.s3_key)
    else:
        result = extract_key_value_pairs(document_path=args.document_path)

    print(json.dumps(result, ensure_ascii=False, indent=2, default=str))
